:root {
  --bg: #f4f5f7;
  --panel: #ffffff;
  --ink: #1a1d24;
  --muted: #6b7280;
  --border: #e3e6ea;
  --accent: #3b5bdb;
  --accent-ink: #ffffff;
  --danger: #d9480f;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--ink);
}
.topbar {
  display: flex; align-items: center; gap: 24px;
  padding: 14px 24px; background: var(--panel);
  border-bottom: 1px solid var(--border);
  position: sticky; top: 0; z-index: 5;
}
.topbar h1 { font-size: 20px; margin: 0; }
.search { flex: 1; max-width: 480px; }
.search input {
  width: 100%; padding: 9px 14px; border: 1px solid var(--border);
  border-radius: 8px; font-size: 14px;
}
.layout { display: flex; gap: 24px; padding: 24px; max-width: 1100px; margin: 0 auto; }
.sidebar { width: 220px; flex-shrink: 0; }
.sidebar h2 { font-size: 13px; text-transform: uppercase; color: var(--muted); letter-spacing: .04em; margin: 24px 0 8px; }
.content { flex: 1; min-width: 0; }
.tag-list { list-style: none; margin: 0; padding: 0; }
.tag-list li { margin-bottom: 2px; }
.tag-filter {
  width: 100%; text-align: left; background: none; border: none;
  padding: 7px 10px; border-radius: 6px; cursor: pointer; font-size: 14px; color: var(--ink);
  display: flex; justify-content: space-between; gap: 8px;
}
.tag-filter:hover { background: #eef0f3; }
.tag-filter.active { background: var(--accent); color: var(--accent-ink); }
.tag-filter .count { color: var(--muted); font-size: 12px; }
.tag-filter.active .count { color: rgba(255,255,255,.85); }
.btn {
  padding: 9px 14px; border: 1px solid var(--border); background: var(--panel);
  border-radius: 8px; cursor: pointer; font-size: 14px; color: var(--ink);
}
.btn:hover { background: #eef0f3; }
.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.btn.primary:hover { filter: brightness(1.05); }
.btn.block { width: 100%; }
.bookmark-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.card {
  background: var(--panel); border: 1px solid var(--border); border-radius: 10px;
  padding: 16px 18px;
}
.card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.card a.title { font-size: 16px; font-weight: 600; color: var(--accent); text-decoration: none; word-break: break-word; }
.card a.title:hover { text-decoration: underline; }
.card .url { font-size: 12px; color: var(--muted); word-break: break-all; margin: 2px 0 0; }
.card .desc { margin: 10px 0 0; font-size: 14px; line-height: 1.5; }
.card .tags { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 6px; }
.chip { background: #eef0f3; color: #495057; font-size: 12px; padding: 3px 9px; border-radius: 20px; }
.card-actions { display: flex; gap: 6px; flex-shrink: 0; }
.icon-btn { border: none; background: none; cursor: pointer; font-size: 13px; color: var(--muted); padding: 4px 6px; border-radius: 6px; }
.icon-btn:hover { background: #eef0f3; color: var(--ink); }
.icon-btn.del:hover { color: var(--danger); }
.empty { text-align: center; color: var(--muted); padding: 60px 20px; font-size: 15px; }
.hidden { display: none !important; }
.modal {
  position: fixed; inset: 0; background: rgba(20,23,30,.45);
  display: flex; align-items: center; justify-content: center; z-index: 20; padding: 20px;
}
.modal-box { background: var(--panel); border-radius: 12px; padding: 24px; width: 100%; max-width: 460px; }
.modal-box h2 { margin: 0 0 16px; font-size: 18px; }
.modal-box label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 12px; }
.modal-box input, .modal-box textarea {
  width: 100%; margin-top: 5px; padding: 9px 11px; border: 1px solid var(--border);
  border-radius: 8px; font-size: 14px; font-family: inherit; font-weight: 400;
}
.modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 8px; }
@media (max-width: 720px) {
  .layout { flex-direction: column; }
  .sidebar { width: 100%; }
}

